content:
Save as `index.html` and open it in a modern browser. The scene uses only the Three.js core ES module from cdnjs; camera orbit, pan, zoom, and touch controls are implemented directly.

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Rock-Cut Buddhist Monastery Terrace</title>

  <style>
    :root {
      color-scheme: dark;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background: #a9c1cc;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      touch-action: none;
    }

    #title {
      position: fixed;
      top: 20px;
      left: 22px;
      z-index: 10;
      max-width: min(420px, calc(100vw - 44px));
      color: #fff8e9;
      pointer-events: none;
      text-shadow: 0 2px 14px rgba(24, 20, 15, 0.55);
    }

    #title h1 {
      margin: 0 0 6px;
      font-size: clamp(20px, 3vw, 34px);
      font-weight: 650;
      letter-spacing: 0.025em;
    }

    #title p {
      margin: 0;
      color: rgba(255, 248, 233, 0.78);
      font-size: 13px;
      line-height: 1.5;
    }

    #controls {
      position: fixed;
      right: 18px;
      bottom: 18px;
      z-index: 20;
      display: flex;
      gap: 8px;
      padding: 8px;
      border: 1px solid rgba(255, 255, 255, 0.2);
      border-radius: 12px;
      color: white;
      background: rgba(30, 28, 24, 0.64);
      box-shadow: 0 8px 28px rgba(0, 0, 0, 0.2);
      backdrop-filter: blur(12px);
    }

    #controls button {
      appearance: none;
      border: 1px solid rgba(255, 255, 255, 0.16);
      border-radius: 8px;
      padding: 8px 11px;
      color: white;
      background: rgba(255, 255, 255, 0.08);
      font: inherit;
      font-size: 12px;
      cursor: pointer;
    }

    #controls button:hover {
      background: rgba(255, 255, 255, 0.16);
    }

    #hint {
      position: fixed;
      left: 22px;
      bottom: 20px;
      z-index: 10;
      color: rgba(255, 248, 233, 0.76);
      font-size: 11px;
      letter-spacing: 0.025em;
      pointer-events: none;
      text-shadow: 0 1px 8px rgba(0, 0, 0, 0.45);
    }

    @media (max-width: 600px) {
      #title {
        top: 14px;
        left: 14px;
      }

      #hint {
        display: none;
      }

      #controls {
        right: 10px;
        bottom: 10px;
      }
    }
  </style>
</head>

<body>
  <div id="title">
    <h1>Cliffside monastery terrace</h1>
    <p>
      Four rock-cut levels, arched monastic cells, a central assembly hall,
      zigzag stairways, edge stupas, and a continuous low parapet.
    </p>
  </div>

  <div id="hint">
    Drag to orbit · Shift/right-drag to pan · Wheel/pinch to zoom · Double-click to reset
  </div>

  <div id="controls">
    <button id="reset">Reset view</button>
    <button id="top">Top view</button>
  </div>

  <script type="module">
    import * as THREE from
      "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // -------------------------------------------------------------------------
    // Renderer, scene, and camera
    // -------------------------------------------------------------------------

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.05;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.domElement.setAttribute(
      "aria-label",
      "Interactive three-dimensional Buddhist rock-cut monastery terrace"
    );
    document.body.prepend(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xa9c1cc);
    scene.fog = new THREE.FogExp2(0xa9c1cc, 0.0115);

    const camera = new THREE.PerspectiveCamera(
      43,
      window.innerWidth / window.innerHeight,
      0.1,
      180
    );

    const maxAnisotropy = renderer.capabilities.getMaxAnisotropy();

    // -------------------------------------------------------------------------
    // Procedural stone textures
    // -------------------------------------------------------------------------

    function mulberry32(seed) {
      return function () {
        let t = seed += 0x6D2B79F5;
        t = Math.imul(t ^ (t >>> 15), t | 1);
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
      };
    }

    function createStoneTextures() {
      const size = 256;
      const random = mulberry32(7319);

      const colorCanvas = document.createElement("canvas");
      const bumpCanvas = document.createElement("canvas");
      colorCanvas.width = colorCanvas.height = size;
      bumpCanvas.width = bumpCanvas.height = size;

      const colorContext = colorCanvas.getContext("2d");
      const bumpContext = bumpCanvas.getContext("2d");
      const colorImage = colorContext.createImageData(size, size);
      const bumpImage = bumpContext.createImageData(size, size);

      for (let y = 0; y < size; y++) {
        for (let x = 0; x < size; x++) {
          const index = (y * size + x) * 4;
          const grain = (random() - 0.5) * 34;
          const band =
            Math.sin(y * 0.105) * 5 +
            Math.sin(y * 0.027 + x * 0.012) * 2;

          colorImage.data[index] = 158 + grain + band;
          colorImage.data[index + 1] = 151 + grain + band;
          colorImage.data[index + 2] = 137 + grain + band;
          colorImage.data[index + 3] = 255;

          const bump = 128 + grain * 1.4 + band * 2;
          bumpImage.data[index] = bump;
          bumpImage.data[index + 1] = bump;
          bumpImage.data[index + 2] = bump;
          bumpImage.data[index + 3] = 255;
        }
      }

      colorContext.putImageData(colorImage, 0, 0);
      bumpContext.putImageData(bumpImage, 0, 0);

      // Horizontal fractures and weathered bands.
      for (let i = 0; i < 28; i++) {
        const y = random() * size;
        const x = random() * size;
        const length = 18 + random() * 90;

        colorContext.strokeStyle = `rgba(75, 67, 56, ${0.05 + random() * 0.12})`;
        colorContext.lineWidth = 0.5 + random() * 1.4;
        colorContext.beginPath();
        colorContext.moveTo(x, y);
        colorContext.bezierCurveTo(
          x + length * 0.3,
          y + (random() - 0.5) * 8,
          x + length * 0.7,
          y + (random() - 0.5) * 8,
          x + length,
          y + (random() - 0.5) * 5
        );
        colorContext.stroke();

        bumpContext.strokeStyle = "rgba(45, 45, 45, 0.3)";
        bumpContext.lineWidth = 1;
        bumpContext.beginPath();
        bumpContext.moveTo(x, y);
        bumpContext.lineTo(x + length, y + (random() - 0.5) * 4);
        bumpContext.stroke();
      }

      const colorTexture = new THREE.CanvasTexture(colorCanvas);
      colorTexture.colorSpace = THREE.SRGBColorSpace;
      colorTexture.wrapS = colorTexture.wrapT = THREE.RepeatWrapping;
      colorTexture.repeat.set(3, 3);
      colorTexture.anisotropy = maxAnisotropy;

      const bumpTexture = new THREE.CanvasTexture(bumpCanvas);
      bumpTexture.wrapS = bumpTexture.wrapT = THREE.RepeatWrapping;
      bumpTexture.repeat.set(3, 3);
      bumpTexture.anisotropy = maxAnisotropy;

      return { colorTexture, bumpTexture };
    }

    const { colorTexture, bumpTexture } = createStoneTextures();

    const materials = {
      stone: new THREE.MeshStandardMaterial({
        map: colorTexture,
        bumpMap: bumpTexture,
        bumpScale: 0.12,
        color: 0xd4c8ad,
        roughness: 0.96
      }),
      darkStone: new THREE.MeshStandardMaterial({
        map: colorTexture,
        bumpMap: bumpTexture,
        bumpScale: 0.16,
        color: 0x817868,
        roughness: 1
      }),
      rock: new THREE.MeshStandardMaterial({
        map: colorTexture,
        bumpMap: bumpTexture,
        bumpScale: 0.2,
        color: 0x938875,
        roughness: 1,
        flatShading: true
      }),
      cave: new THREE.MeshBasicMaterial({ color: 0x120f0c }),
      wood: new THREE.MeshStandardMaterial({
        color: 0x493526,
        roughness: 0.88
      }),
      roof: new THREE.MeshStandardMaterial({
        color: 0x302b27,
        roughness: 0.82
      }),
      gold: new THREE.MeshStandardMaterial({
        color: 0xc69b45,
        metalness: 0.55,
        roughness: 0.4
      }),
      lamp: new THREE.MeshStandardMaterial({
        color: 0xffd28a,
        emissive: 0xff9f32,
        emissiveIntensity: 2.2,
        roughness: 0.45
      })
    };

    // -------------------------------------------------------------------------
    // Geometry helpers
    // -------------------------------------------------------------------------

    function addMesh(parent, geometry, material, x = 0, y = 0, z = 0) {
      const mesh = new THREE.Mesh(geometry, material);
      mesh.position.set(x, y, z);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function box(
      parent,
      width,
      height,
      depth,
      material,
      x = 0,
      y = 0,
      z = 0,
      castShadow = true,
      receiveShadow = true
    ) {
      const mesh = addMesh(
        parent,
        new THREE.BoxGeometry(width, height, depth),
        material,
        x,
        y,
        z
      );
      mesh.castShadow = castShadow;
      mesh.receiveShadow = receiveShadow;
      return mesh;
    }

    function cylinder(
      parent,
      radiusTop,
      radiusBottom,
      height,
      material,
      x = 0,
      y = 0,
      z = 0,
      segments = 16
    ) {
      return addMesh(
        parent,
        new THREE.CylinderGeometry(
          radiusTop,
          radiusBottom,
          height,
          segments
        ),
        material,
        x,
        y,
        z
      );
    }

    function rock(
      parent,
      x,
      y,
      z,
      scaleX,
      scaleY,
      scaleZ,
      material = materials.rock
    ) {
      const mesh = addMesh(
        parent,
        new THREE.DodecahedronGeometry(1, 0),
        material,
        x,
        y,
        z
      );
      mesh.scale.set(scaleX, scaleY, scaleZ);
      mesh.rotation.set(
        (Math.random() - 0.5) * 0.35,
        Math.random() * Math.PI,
        (Math.random() - 0.5) * 0.35
      );
      return mesh;
    }

    // -------------------------------------------------------------------------
    // Lighting and landscape
    // -------------------------------------------------------------------------

    scene.add(new THREE.HemisphereLight(0xdcebf0, 0x5b4938, 1.65));

    const sun = new THREE.DirectionalLight(0xffe6bc, 3.1);
    sun.position.set(16, 28, 22);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    sun.shadow.camera.left = -31;
    sun.shadow.camera.right = 31;
    sun.shadow.camera.top = 28;
    sun.shadow.camera.bottom = -18;
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 75;
    sun.shadow.bias = -0.00035;
    sun.shadow.normalBias = 0.035;
    scene.add(sun);

    const fill = new THREE.DirectionalLight(0xaac8df, 0.75);
    fill.position.set(-18, 12, -12);
    scene.add(fill);

    const ground = box(
      scene,
      72,
      0.4,
      48,
      materials.darkStone,
      0,
      -0.35,
      4
    );
    ground.castShadow = false;

    // Distant low-poly mountain silhouettes.
    const mountainMaterial = new THREE.MeshStandardMaterial({
      color: 0x647980,
      roughness: 1,
      flatShading: true
    });

    for (const [x, z, radius, height] of [
      [-24, -24, 11, 15],
      [-7, -30, 14, 19],
      [15, -27, 12, 17],
      [31, -25, 10, 14]
    ]) {
      const mountain = addMesh(
        scene,
        new THREE.ConeGeometry(radius, height, 5),
        mountainMaterial,
        x,
        height * 0.5 - 1,
        z
      );
      mountain.castShadow = false;
    }

    const sunDisc = addMesh(
      scene,
      new THREE.CircleGeometry(3.2, 32),
      new THREE.MeshBasicMaterial({ color: 0xffe2a1 }),
      -27,
      28,
      -42
    );
    sunDisc.castShadow = false;

    // -------------------------------------------------------------------------
    // Main cliff face
    // -------------------------------------------------------------------------

    const cliffGeometry = new THREE.PlaneGeometry(46, 20, 40, 16);
    const cliffPositions = cliffGeometry.attributes.position;

    for (let i = 0; i < cliffPositions.count; i++) {
      const x = cliffPositions.getX(i);
      const y = cliffPositions.getY(i);
      const noise = Math.sin(x * 0.43) * 0.14 +
        Math.cos(y * 0.37) * 0.11 +
        (Math.random() - 0.5) * 0.75;
      cliffPositions.setZ(i, noise);
    }
    cliffGeometry.computeVertexNormals();

    const cliff = addMesh(
      scene,
      cliffGeometry,
      materials.darkStone,
      0,
      8.5,
      -4.25
    );
    cliff.receiveShadow = true;

    // Horizontal rock strata behind the carved facades.
    for (let i = 0; i < 7; i++) {
      const width = 34 + Math.random() * 8;
      const height = 0.55 + Math.random() * 0.45;
      box(
        scene,
        width,
        height,
        0.85,
        i % 2 ? materials.rock : materials.darkStone,
        (Math.random() - 0.5) * 3,
        0.8 + i * 1.15,
        -4.02
      );
    }

    // Side masses give the cliff a cut, irregular silhouette.
    for (const side of [-1, 1]) {
      for (let i = 0; i < 7; i++) {
        rock(
          scene,
          side * (18.5 + Math.random() * 2.4),
          1.2 + i * 1.75,
          -4.0 + Math.random() * 1.2,
          2.2 + Math.random() * 2.2,
          1.8 + Math.random() * 2.2,
          2.0 + Math.random() * 1.8
        );
      }
    }

    // -------------------------------------------------------------------------
    // Four terrace levels
    // -------------------------------------------------------------------------

    const levels = [
      { y: 0.65, front: 4.8 },
      { y: 2.45, front: 4.0 },
      { y: 4.25, front: 3.2 },
      { y: 6.05, front: 2.4 }
    ];

    function createCave(level, x, index) {
      const base = level.y + 0.12;
      const width = 1.5;
      const height = 1.9;
      const radius = width * 0.5;
      const spring = height - radius;

      const shape = new THREE.Shape();
      shape.moveTo(-radius, 0);
      shape.lineTo(radius, 0);
      shape.lineTo(radius, spring);
      shape.absarc(0, spring, radius, 0, Math.PI, false);
      shape.lineTo(-radius, 0);

      const opening = addMesh(
        scene,
        new THREE.ShapeGeometry(shape),
        materials.cave,
        x,
        base,
        -3.39
      );
      opening.castShadow = false;

      const frameZ = -3.25;

      box(
        scene,
        0.18,
        spring,
        0.18,
        materials.rock,
        x - radius - 0.08,
        base + spring * 0.5,
        frameZ
      );
      box(
        scene,
        0.18,
        spring,
        0.18,
        materials.rock,
        x + radius + 0.08,
        base + spring * 0.5,
        frameZ
      );
      box(
        scene,
        width + 0.28,
        0.18,
        0.22,
        materials.rock,
        x,
        base + spring + 0.07,
        frameZ
      );

      const arch = addMesh(
        scene,
        new THREE.TorusGeometry(radius, 0.12, 6, 20, Math.PI),
        materials.rock,
        x,
        base + spring,
        -3.22
      );
      arch.castShadow = false;

      // Narrow projecting ledge in front of every cave.
      box(
        scene,
        width + 0.72,
        0.12,
        0.7,
        materials.stone,
        x,
        base - 0.11,
        -2.94
      );

      // A few oil lamps provide warm depth.
      if (index % 3 === 0) {
        const lamp = addMesh(
          scene,
          new THREE.SphereGeometry(0.075, 10, 8),
          materials.lamp,
          x + 0.2,
          base + 0.42,
          -3.08
        );
        lamp.castShadow = false;

        const light = new THREE.PointLight(0xffa84d, 3.2, 4.2, 2);
        light.position.set(x + 0.2, base + 0.45, -2.9);
        scene.add(light);
      }
    }

    const cavePositions = [-14.2, -11.7, -9.2, -6.7, 6.7, 9.2, 11.7, 14.2];

    levels.forEach((level, levelIndex) => {
      const depth = level.front + 3.6;
      const centerZ = (level.front - 3.6) * 0.5;

      // Main terrace slab.
      box(
        scene,
        36,
        0.34,
        depth,
        materials.stone,
        0,
        level.y - 0.17,
        centerZ
      );

      // Rock-cut front retaining wall.
      box(
        scene,
        36,
        1.25,
        0.32,
        materials.darkStone,
        0,
        level.y - 0.64,
        level.front
      );

      // Side walls.
      for (const side of [-1, 1]) {
        box(
          scene,
          0.38,
          1.25,
          depth,
          materials.stoneDark,
          side * 18.1,
          level.y - 0.625,
          centerZ
        );
      }

      // Low parapet follows the stepped cliff contour.
      const parapetSegments = [
        [-17.45, -10.35],
        [-5.25, 5.25],
        [10.35, 17.45]
      ];

      for (const [start, end] of parapetSegments) {
        const width = end - start;
        const center = (start + end) * 0.5;

        box(
          scene,
          width,
          0.55,
          0.28,
          materials.stone,
          center,
          level.y + 0.275,
          level.front + 0.32
        );

        box(
          scene,
          width + 0.08,
          0.12,
          0.4,
          materials.stone,
          center,
          level.y + 0.61,
          level.front + 0.32
        );
      }

      // Broad landing where the two side stairways turn.
      box(
        scene,
        20,
        0.24,
        1.1,
        materials.stone,
        0,
        level.y - 0.02,
        level.front
      );

      // Small edge blocks give the terrace a hand-built appearance.
      for (let i = 0; i < 8; i++) {
        const x = -16.5 + i * 4.5;
        box(
          scene,
          1.05,
          0.22,
          0.55,
          materials.rock,
          x,
          level.y + 0.08,
          level.front + 0.48
        );
      }

      // Cave row, interrupted only by the central assembly hall.
      cavePositions.forEach((x, index) => {
        if (levelIndex === 1 && Math.abs(x) < 4.2) return;
        createCave(level, x, index);
      });

      // Small stupas at both terrace edges.
      for (const side of [-1, 1]) {
        createStupa(scene, side * 16.45, level.y, level.front - 1.0, 0.78);
      }
    });

    function createStupa(parent, x, y, z, scale) {
      const baseY = y + 0.1;

      box(
        parent,
        0.9 * scale,
        0.34 * scale,
        0.9 * scale,
        materials.stone,
        x,
        baseY + 0.17 * scale,
        z
      );

      cylinder(
        parent,
        0.56 * scale,
        0.64 * scale,
        0.5 * scale,
        materials.stone,
        x,
        baseY + 0.55 * scale,
        z,
        18
      );

      cylinder(
        parent,
        0.57 * scale,
        0.57 * scale,
        0.08 * scale,
        materials.gold,
        x,
        baseY + 0.69 * scale,
        z,
        18
      );

      const dome = addMesh(
        parent,
        new THREE.SphereGeometry(
          0.56 * scale,
          20,
          10,
          0,
          Math.PI * 2,
          0,
          Math.PI * 0.5
        ),
        materials.stone,
        x,
        baseY + 0.8 * scale,
        z
      );
      dome.castShadow = true;

      box(
        parent,
        0.72 * scale,
        0.28 * scale,
        0.72 * scale,
        materials.stone,
        x,
        baseY + 1.43 * scale,
        z
      );

      addMesh(
        parent,
        new THREE.ConeGeometry(0.28 * scale, 0.55 * scale, 8),
        materials.gold,
        x,
        baseY + 1.78 * scale,
        z
      );
    }

    // -------------------------------------------------------------------------
    // Central assembly hall
    // -------------------------------------------------------------------------

    const hallLevel = levels[1];
    const hallBase = hallLevel.y + 0.1;
    const hallZ = hallLevel.front - 1.55;

    // Rock-cut shaft behind the hall.
    box(
      scene,
      7.4,
      3.1,
      5.5,
      materials.darkStone,
      0,
      hallBase + 1.55,
      -0.75
    );

    // Hall enclosure.
    box(
      scene,
      7.4,
      3.1,
      0.32,
      materials.darkStone,
      0,
      hallBase + 1.55,
      1.95
    );

    for (const side of [-1, 1]) {
      box(
        scene,
        0.32,
        3.1,
        2.5,
        materials.stone,
        side * 3.65,
        hallBase + 1.55,
        2.45
      );
    }

    // Recessed dark doorway.
    box(
      scene,
      2.25,
      2.45,
      0.12,
      materials.cave,
      0,
      hallBase + 1.225,
      2.13
    );

    for (const side of [-1, 1]) {
      box(
        scene,
        0.12,
        2.45,
        0.16,
        materials.rock,
        side * 1.16,
        hallBase + 1.225,
        2.14
      );
    }

    // Six square wooden columns.
    for (const x of [-3.25, -1.62, 0, 1.62, 3.25]) {
      box(
        scene,
        0.28,
        3.05,
        0.28,
        materials.wood,
        x,
        hallBase + 1.525,
        2.72
      );

      box(
        scene,
        0.58,
        0.18,
        0.58,
        materials.stone,
        x,
        hallBase + 3.08,
        2.72
      );
    }

    box(
      scene,
      7.9,
      0.28,
      2.75,
      materials.stone,
      0,
      hallBase + 3.22,
      2.45
    );

    box(
      scene,
      8.35,
      0.22,
      3.0,
      materials.roof,
      0,
      hallBase + 3.43,
      2.45
    );

    box(
      scene,
      8.5,
      0.13,
      0.36,
      materials.darkStone,
      0,
      hallBase + 3.6,
      2.45
    );

    cylinder(
      scene,
      0.11,
      0.16,
      0.42,
      materials.gold,
      0,
      hallBase + 3.85,
      2.45,
      10
    );

    addMesh(
      scene,
      new THREE.SphereGeometry(0.14, 12, 8),
